optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/xml.rs b/tools/bot-evaluation/src/xml.rs
index 3accb4ad..552eabec 100644
--- a/tools/bot-evaluation/src/xml.rs
+++ b/tools/bot-evaluation/src/xml.rs
@@ -139,8 +139,8 @@ pub fn parse(source: &str, root: &str) -> Result<Value> {
 }
 fn emit(writer: &mut Writer<Vec<u8>>, name: &str, value: &Value) -> Result<()> {
     if !name
-        .chars()
-        .all(|c| c.is_ascii_alphanumeric() || "_-".contains(c))
+        .bytes()
+        .all(|c| c.is_ascii_alphanumeric() || b"_-".contains(&c))
     {
         return Err("Invalid XML field".into());
     }
